// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SubjectOffering) predicate.SubjectOffering {
	return predicate.SubjectOffering(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SubjectOffering) predicate.SubjectOffering {
	return predicate.SubjectOffering(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SubjectOffering) predicate.SubjectOffering {
	return predicate.SubjectOffering(sql.NotPredicates(p))
}
